a575b763 Refactor includes logic (#781)
 libyara/compiler.c | 115 +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++----------------------------------
 tests/test-rules.c |  11 ++++++++++-
 2 files changed, 91 insertions(+), 35 deletions(-)
commit a575b7639279aefbb1ddde09b58355cdb0390f7d
Author: Victor M. Alvarez <plusvic@gmail.com>
Date:   Wed Nov 1 20:22:44 2017 +0100

    Refactor includes logic (#781)

    * Refactor logic for "include" statement.

    * Fix errors.

    * Include <sys/stat.h> in Windows too.

    * Replace _WIN32 with _MSC_VER.

diff --git a/libyara/compiler.c b/libyara/compiler.c
index 94286475..f41a12ed 100644
--- a/libyara/compiler.c
+++ b/libyara/compiler.c
@@ -28,9 +28,17 @@ SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.
 */

 #include <assert.h>
+#include <fcntl.h>
 #include <stddef.h>
 #include <stdio.h>
 #include <string.h>
+#include <sys/stat.h>
+
+#ifdef _MSC_VER
+#include <io.h>
+#else
+#include <unistd.h>
+#endif

 #include <yara/libyara.h>
 #include <yara/utils.h>
@@ -44,14 +52,13 @@ SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.


 static void _yr_compiler_default_include_free(
-  const char* callback_result_ptr,
-  void* user_data)
+    const char* callback_result_ptr,
+    void* user_data)
 {
   if(callback_result_ptr != NULL)
   {
     yr_free((void*)callback_result_ptr);
   }
-
 }


@@ -61,39 +68,46 @@ const char* _yr_compiler_default_include_callback(
     const char* calling_rule_namespace,
     void* user_data)
 {
-  char buffer[1024];
-  char* s = NULL;
-  #ifdef _WIN32
+  #ifndef _MSC_VER
+  struct stat stbuf;
+  #endif
+
+  #ifdef _MSC_VER
   char* b = NULL;
   #endif
+
+  char* s = NULL;
   char* f;
-  FILE* fh;
   char* file_buffer;
-  long file_length;
+  char buffer[1024];
+
+  #ifdef _MSC_VER
+  long file_size;
+  #else
+  off_t file_size;
+  #endif
+
+  int fd = -1;

   if (calling_rule_filename != NULL)
-  {
     strlcpy(buffer, calling_rule_filename, sizeof(buffer));
-  }
   else
-  {
     buffer[0] = '\0';
-  }

   s = strrchr(buffer, '/');

-  #ifdef _WIN32
+  #ifdef _MSC_VER
   b = strrchr(buffer, '\\'); // in Windows both path delimiters are accepted
   #endif

-  #ifdef _WIN32
+  #ifdef _MSC_VER
   if (s != NULL || b != NULL)
   #else
   if (s != NULL)
   #endif
   {
-    #ifdef _WIN32
-    f = (b > s)? (b + 1): (s + 1);
+    #ifdef _MSC_VER
+    f = (b > s) ? (b + 1) : (s + 1);
     #else
     f = s + 1;
     #endif
@@ -101,59 +115,92 @@ const char* _yr_compiler_default_include_callback(
     strlcpy(f, include_name, sizeof(buffer) - (f - buffer));

     f = buffer;
+
     // SECURITY: Potential for directory traversal here.
-    fh = fopen(buffer, "rb");
+    #ifdef _MSC_VER
+    _sopen_s(&fd, f, _O_RDONLY, _SH_DENYRW, _S_IREAD);
+    #else
+    fd = open(f, O_RDONLY);
+    #endif

     // if include file was not found relative to current source file,
     // try to open it with path as specified by user (maybe user wrote
     // a full path)
-    if (fh == NULL)
+    if (fd == -1)
     {
       f = (char*) include_name;
-      // SECURITY: Potential for directory traversal here.
-      fh = fopen(include_name, "rb");
     }
   }
   else
   {
     f = (char*) include_name;
+  }
+
+  if (fd == -1)
+  {
     // SECURITY: Potential for directory traversal here.
-    fh = fopen(include_name, "rb");
+    #ifdef _MSC_VER
+    _sopen_s(&fd, f, _O_RDONLY, _SH_DENYRW, _S_IREAD);
+    #else
+    fd = open(f, O_RDONLY);
+    #endif
   }

-  if (fh == NULL)
+  if (fd == -1)
     return NULL;

-  fseek(fh, 0, SEEK_END);
-  file_length = ftell(fh);
-  fseek(fh, 0, SEEK_SET);
-
-  if (file_length == -1)
+  #ifdef _MSC_VER
+  file_size = _filelength(fd);
+  if (file_size == -1)
   {
-    fclose(fh);
+    _close(fd);
     return NULL;
   }
+  #else
+  if ((fstat(fd, &stbuf) != 0) || (!S_ISREG(stbuf.st_mode)))
+  {
+    close(fd);
+    return NULL;
+  }
+  file_size = stbuf.st_size;
+  #endif

-  file_buffer = (char*) yr_malloc(file_length + 1);
+  file_buffer = (char*) yr_malloc(file_size + 1);

   if (file_buffer == NULL)
   {
-    fclose(fh);
+    #ifdef _MSC_VER
+    _close(fd);
+    #else
+    close(fd);
+    #endif
+
     return NULL;
   }

-  if (file_length != fread(file_buffer, 1, file_length, fh))
+  if (file_size != read(fd, file_buffer, file_size))
   {
     yr_free(file_buffer);
-    fclose(fh);
+
+    #ifdef _MSC_VER
+    _close(fd);
+    #else
+    close(fd);
+    #endif
+
     return NULL;
   }
   else
   {
-    file_buffer[file_length] = '\0';
+    file_buffer[file_size] = '\0';
   }

-  fclose(fh);
+  #ifdef _MSC_VER
+  _close(fd);
+  #else
+  close(fd);
+  #endif
+
   return file_buffer;
 }
